+    let actual_b = journal.events_for_run(run_b)?;
+    let expected_b = vec![JournalEvent::RunFinished {
+        run: run_b,
+        seq: EventSeq::new(0),
+        result: SlotIdx::new(1),
+        attempt: 1,
+    }];
+    assert_eq!(
+        actual_b, expected_b,
+        "run_b event persisted after strict decision"
+    );
