    // pending-scheduled boundary; recovery is the gate under test.
    runtime.configure_live_policy(
        vb_core::policy::PolicyDigest::from_bytes([0x80u8; 32]),
        vb_core::policy::PolicyRule {
            action,
            code: vb_core::policy::DecisionCode::Allowed,
        },
    )?;
    runtime.submit_direct_with_inputs_grants_and_contracts(
        run,
        workflow,
        Box::from([(SlotIdx::ZERO, SlotValue::I64(9))]),
        action_grants(action),
        Box::from([contract]),
    )?;
    runtime.tick_all()?;
    assert!(
        runtime
            .lookup_pending_action_ticket(run, u64::from(StepIdx::ZERO.get()))
            .is_some(),
        "expected pending action before recovery"
    );
    drop(runtime);
    let _ = dir;
    Ok(())
}

