        let last = events
            .last()
            .ok_or("expected at least one prior event for seq computation")?;
        let next = last
            .seq()
            .get()
            .checked_add(1)
            .ok_or("expected seq arithmetic to stay within u64")?;
        EventSeq::new(next)
