fn assert_stored_emergency_decisions(
…
    run: RunId,
    expected_first: &DecisionRecord,
    expected_second: &DecisionRecord,
) -> CaseResult<()> {
    let events = vb_storage::read_run_events(journal, run)?;
    let decision_events: Vec<_> = events
        .iter()
