    inner: SharedRuntimeJournal,
    policy_port_called: Arc<AtomicBool>,
    captured_decision: Arc<Mutex<Option<vb_core::policy::DecisionRecord>>>,
    captured_calls: Arc<Mutex<Vec<(vb_core::policy::DecisionRecord, EventSeq)>>>,
}

